package com.coraline.secrets;

import com.coraline.feast.*;
import net.minecraft.gametest.framework.*;
import net.minecraftforge.gametest.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import java.util.*;

@GameTestHolder("coraline") @PrefixGameTestTemplate(false)
public final class ReconciliationGameTests {
    @GameTest(template="empty") public static void allScoldingUsesSeriousRecordingsIncludingSavedMinorQueue(GameTestHelper h){
        var p=fixture(h);var n=SecretTransactions.state(p).dialogue;var state=SecretDialogue.state(p);
        SecretDialogue.queueScolding(p,Reconciliation.Category.MINOR,state);
        h.assertTrue(n.getString("Queue").startsWith("other_mother_scolding_serious_"),"Minor encounter selected minor recording");
        n.putString("Pool",Reconciliation.pool(Reconciliation.Category.MINOR,state).path());n.putString("Queue",Reconciliation.pool(Reconciliation.Category.MINOR,state).sound(0));
        SecretDialogue.useSeriousScolding(p);h.assertTrue(n.getString("Queue").startsWith("other_mother_scolding_serious_"),"Saved minor queue not migrated");h.succeed();
    }
    @GameTest(template="empty") public static void scoldingAllowsNearbyMovementAndConfiscatesOnlyEvidence(GameTestHelper h){
        var p=fixture(h);var s=SecretTransactions.state(p);var origin=p.position();
        SecretTransactions.issue(p,"house_codes");p.getInventory().setItem(8,new ItemStack(Items.DIAMOND,3));
        SecretDialogue.confront(p,SecretDialogue.Event.SECRET_AREA_CAUGHT,SecretDialogue.state(p));
        p.setPos(origin.add(2,0,0));Reconciliation.hold(p);
        h.assertTrue(p.distanceToSqr(origin.add(2,0,0))<.01,"Nearby movement was frozen");
        finish(p);Reconciliation.advance(p);
        h.assertTrue(s.issued.isEmpty()&&s.exposed.contains("house_codes"),"Forbidden item not confiscated");
        h.assertTrue(p.getInventory().getItem(8).is(Items.DIAMOND)&&p.getInventory().getItem(8).getCount()==3,"Ordinary gear confiscated");
        SecretTransactions.confiscate(p);h.assertTrue(s.issued.isEmpty(),"Confiscation not idempotent");h.succeed();
    }
    @GameTest(template="empty") public static void thresholdCatchClosesPriorWindow(GameTestHelper h){var p=fixture(h);var l=OtherMotherLoop.scene(p).loop;l.phase=OtherMotherLoopState.Phase.WINDOW;l.arrivalDeadline=OtherMotherLoop.now(p)+6000;l.suspicion=1;SecretDialogue.confront(p,SecretDialogue.Event.BLACKMAIL_REJECTED,SecretDialogue.state(p));h.assertTrue(l.phase==OtherMotherLoopState.Phase.EXPLORING&&l.arrivalDeadline==0&&Reconciliation.active(p),"Old activity window bypassed story threshold");h.assertTrue(l.secrets.dialogue.getString("Queue").contains("reject"),"Lost rejection outcome");h.succeed();}
    private static ServerPlayer fixture(GameTestHelper h){var original=SecretsGameTests.fixture(h);var p=new net.minecraftforge.common.util.FakePlayer(original.serverLevel(),original.getGameProfile()){@Override public void teleportTo(net.minecraft.server.level.ServerLevel level,double x,double y,double z,float yaw,float pitch){setPos(x,y,z);setYRot(yaw);setXRot(pitch);}};p.getPersistentData().merge(original.getPersistentData());p.setPos(original.position());var r=SecretWorld.realm(p);for(int x=-4;x<=4;x++)for(int z=-4;z<=4;z++)p.serverLevel().setBlock(r.porch.offset(x,-1,z),Blocks.STONE.defaultBlockState(),2);return p;}
    private static void finish(ServerPlayer p){var n=SecretTransactions.state(p).dialogue;String sound=n.getString("Queue");n.remove("Queue");n.putString("Playing",sound);n.putBoolean("Finished",true);n.putLong("Until",OtherMotherLoop.now(p));}
    @GameTest(template="empty") public static void tenPoolsAndMappings(GameTestHelper h){h.assertTrue(Reconciliation.pools().size()==10,"Ten scolding pools missing");for(var pool:Reconciliation.pools())h.assertTrue(pool.size()==1&&VisitAudio.SOUNDS.containsKey(pool.sound(0)),"Unregistered scold");for(var e:SecretDialogue.Event.values())if(e!=SecretDialogue.Event.BLACKMAIL_OFFER)h.assertTrue(Reconciliation.category(e)==(e==SecretDialogue.Event.ORDINARY_AREA_CAUGHT?Reconciliation.Category.MINOR:Reconciliation.Category.SERIOUS),"Wrong category");h.succeed();}
    @GameTest(template="empty") public static void debriefPreservesPermanentStateAndAdvancesOnce(GameTestHelper h){var p=fixture(h);var scene=OtherMotherLoop.scene(p);var s=scene.loop.secrets;OtherMotherLoop.relationship(p,.7F,.2F);s.exposed.add("soulglass");s.recalculate();scene.loop.gifts.add(new ItemStack(Items.DIAMOND,3));var previous=scene.loop.activity;int visits=scene.loop.visits,generation=scene.loop.generation;var captured=SecretDialogue.state(p);SecretDialogue.confront(p,SecretDialogue.Event.SECRET_AREA_CAUGHT,captured);h.assertTrue(Reconciliation.active(p),"No reconciliation");h.assertFalse(OtherMotherLoop.afterReconciliation(p),"Duplicate premature proposal");finish(p);Reconciliation.advance(p);h.assertTrue(s.dialogue.getString("Queue").equals(Reconciliation.pool(Reconciliation.Category.SERIOUS,captured).sound(0)),"Wrong scold");OtherMotherLoop.relationship(p,.1F,.8F);finish(p);Reconciliation.advance(p);h.assertFalse(Reconciliation.active(p),"Conversation never cleared");h.assertTrue(scene.loop.phase==OtherMotherLoopState.Phase.PROPOSAL&&scene.loop.activity!=previous,"Next distinct activity missing");h.assertTrue(scene.loop.trust==.1F&&scene.loop.suspicion==.8F&&s.exposed.contains("soulglass")&&scene.loop.gifts.get(0).getCount()==3&&scene.loop.visits==visits&&scene.loop.generation==generation,"Forgiveness reset story/rewards");var next=scene.loop.activity;Reconciliation.advance(p);h.assertTrue(scene.loop.activity==next&&!OtherMotherLoop.afterReconciliation(p),"Duplicate proposal");h.assertTrue(p.distanceToSqr(SecretWorld.realm(p).porch.getCenter())<16,"Not safely returned home");h.succeed();}
    @GameTest(template="empty") public static void audioDurationAndAckGateScold(GameTestHelper h){var p=fixture(h);SecretDialogue.confront(p,SecretDialogue.Event.SECRET_AREA_CAUGHT,SecretDialogue.state(p));var n=SecretTransactions.state(p).dialogue;finish(p);n.putLong("Until",OtherMotherLoop.now(p)+500);SecretDialogue.tick(p);h.assertTrue(Reconciliation.stage(p).equals("OPENING"),"Ignored audio duration");n.putLong("Until",OtherMotherLoop.now(p));n.putBoolean("Finished",false);SecretDialogue.tick(p);h.assertTrue(Reconciliation.stage(p).equals("OPENING"),"Ignored playback acknowledgement");SecretDialogue.finished(p,n.getString("Playing"));SecretDialogue.tick(p);h.assertTrue(Reconciliation.stage(p).equals("SCOLDING"),"Scold did not follow completed opening");h.succeed();}
    @GameTest(template="empty") public static void missingAudioFallbackIsBounded(GameTestHelper h){var p=fixture(h);SecretDialogue.confront(p,SecretDialogue.Event.SECRET_AREA_CAUGHT,SecretDialogue.state(p));var n=SecretTransactions.state(p).dialogue;finish(p);n.putBoolean("Finished",false);n.putLong("Until",OtherMotherLoop.now(p)-201);SecretDialogue.tick(p);h.assertTrue(Reconciliation.stage(p).equals("SCOLDING"),"Missing ack softlocked flow");h.succeed();}
    @GameTest(template="empty") public static void bellDoesNotInventWanderingOpening(GameTestHelper h){var p=fixture(h);var s=SecretTransactions.state(p);s.search=SecretsState.Search.SEARCHING;OtherMotherLoop.relationship(p,.51F,.2F);var state=SecretDialogue.state(p);MotherSearch.bell(p);h.assertTrue(Reconciliation.stage(p).equals("BELL_RETURN")&&s.dialogue.getString("Queue").isEmpty(),"Bell played wandering opening");h.assertTrue(s.dialogue.getCompound("Reconcile").getString("State").equals(state.id()),"Bell captured post-penalty state");float trust=OtherMotherLoop.scene(p).loop.trust;MotherSearch.bell(p);h.assertTrue(OtherMotherLoop.scene(p).loop.trust==trust,"Bell spam applied penalty");h.succeed();}
    @GameTest(template="empty") public static void suspicionAndScriptedTrapOverride(GameTestHelper h){var p=fixture(h);var l=OtherMotherLoop.scene(p).loop;SecretDialogue.confront(p,SecretDialogue.Event.SECRET_AREA_CAUGHT,SecretDialogue.state(p));l.suspicion=1;Reconciliation.hold(p);h.assertTrue(Reconciliation.active(p)&&!OtherMotherLoop.afterReconciliation(p),"Max suspicion must finish scolding without offering activities");Reconciliation.cancel(p);l.suspicion=.8F;l.secrets.search=SecretsState.Search.SCRIPTED_TRAP;h.assertFalse(Reconciliation.begin(p,Reconciliation.Category.MINOR,SecretDialogue.state(p),false)||OtherMotherLoop.afterReconciliation(p),"Scripted trap bypassed");h.assertTrue(l.secrets.search==SecretsState.Search.SCRIPTED_TRAP,"Trap state cleared");h.succeed();}
    @GameTest(template="empty") public static void disconnectResumesWithoutPenalty(GameTestHelper h){var p=fixture(h);var scene=OtherMotherLoop.scene(p);SecretDialogue.confront(p,SecretDialogue.Event.SECRET_AREA_CAUGHT,SecretDialogue.state(p));Reconciliation.suspend(p);h.assertTrue(Reconciliation.stage(p).equals("SUSPENDED"),"No suspension");scene.loop.secrets=SecretsState.load(scene.loop.secrets.save());Reconciliation.hold(p);Reconciliation.advance(p);h.assertTrue(Reconciliation.stage(p).equals("SCOLDING")&&scene.loop.trust==0&&scene.loop.suspicion==0,"Resume duplicated penalty or failed");Reconciliation.cancel(p);h.assertFalse(Reconciliation.active(p)||SecretDialogue.busy(p),"Cancelled controls remained locked");h.succeed();}
    @GameTest(template="empty") public static void freezeDoesNotLockCameraOrOtherOwner(GameTestHelper h){var p=fixture(h);var other=fixture(h);var original=OtherMotherLoop.scene(other).loop.save();var pos=p.position();SecretDialogue.confront(p,SecretDialogue.Event.ORDINARY_AREA_CAUGHT,SecretDialogue.state(p));p.setPos(pos.add(5,0,0));p.setYRot(73);p.setXRot(24);Reconciliation.hold(p);h.assertTrue(p.distanceToSqr(pos)<.01&&p.getYRot()==73&&p.getXRot()==24,"Movement/camera constraint incorrect");h.assertTrue(OtherMotherLoop.scene(other).loop.save().equals(original),"Another owner changed");h.succeed();}
    @GameTest(template="empty") public static void bothBlackmailOutcomesScoldOnlyAfterCommit(GameTestHelper h){for(int forced:new int[]{0,1}){var p=fixture(h);var s=SecretTransactions.state(p);s.journal.add("house_codes");SecretTransactions.makeBlackmail(p,List.of("house_codes"));SecretTransactions.offer(p,p.getInventory().getItem(0),forced);h.assertFalse(Reconciliation.active(p),"Scold before offer outcome");SecretsGameTests.finishOffer(p);if(forced==1){h.assertFalse(Reconciliation.active(p),"Scold before payout");SecretTransactions.reward(p,0);}h.assertTrue(Reconciliation.active(p)&&s.dialogue.getCompound("Reconcile").getString("Category").equals("SERIOUS"),"Outcome missing serious scold");}h.succeed();}
    @GameTest(template="empty") public static void twoMissedCyclesCanReconcile(GameTestHelper h){var p=fixture(h);var s=SecretTransactions.state(p);for(int run=0;run<2;run++){OtherMotherLoop.scene(p).loop.phase=OtherMotherLoopState.Phase.EXPLORING;MotherSearch.missed(p);h.assertTrue(s.search==SecretsState.Search.MISSED_ACTIVITY_PENDING&&s.pendingTicks>0,"Missed cycle not scheduled");SecretDialogue.confront(p,SecretDialogue.Event.ORDINARY_AREA_CAUGHT,SecretDialogue.state(p));finish(p);Reconciliation.advance(p);finish(p);Reconciliation.advance(p);h.assertTrue(s.pendingTicks==0&&s.search==SecretsState.Search.NORMAL&&OtherMotherLoop.scene(p).loop.phase==OtherMotherLoopState.Phase.PROPOSAL,"Cycle did not restart");}h.succeed();}
}
